<?php
namespace App\Domain\Articles; use App\Domain\Homepage\HomepageCache; use App\Models\HomepageItem; use Illuminate\Support\Facades\Cache; use Throwable; final class ArticleCache { public static function version(int $id):int{try{return (int)Cache::rememberForever("public.articles.version.$id",fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function indexVersion():int{try{return (int)Cache::rememberForever('public.articles.index.version',fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function forget(int $id):void{try{Cache::put("public.articles.version.$id",hrtime(true));Cache::put('public.articles.index.version',hrtime(true));if(HomepageItem::where('article_id',$id)->exists()){HomepageCache::forget();}}catch(Throwable){}} }
